{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Aprepitant, an oral drug containing heteroaromatic and fluorophenyl motifs, has an absolute oral bioavailability of approximately 60–65% in humans, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Brexpiprazole, a fluorophenyl-containing oral drug with heteroaromatic structure, has an absolute bioavailability of about 95% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Olaparib, a fused heteroaromatic lactam with a fluorophenyl group, shows a simulated absolute oral bioavailability of 0.72, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Ketanserin, a fluorophenyl-containing drug, consistently shows systemic availability around 50% across multiple populations, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Melperone, a fluorophenyl-containing oral drug, has an absolute bioavailability of 54 ± 24.2% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues report absolute oral bioavailability values well above the 20% threshold, ranging from about 45% to 95%, and none provide affirmative evidence of low bioavailability. Although Morgan similarities are low, the consistent direction across diverse oral drugs with fluorophenyl and heteroaromatic features supports a high bioavailability prediction for the query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.26), limiting structural transferability.",
    "No evidence specifically addresses potential solubility, permeability, or first-pass metabolism liabilities of the query.",
    "No human pharmacokinetic data exist for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

